import { Component } from '@angular/core';
import { UserFeedbackService } from 'src/app/services/user-feedback.service';
import { Feedback } from 'src/app/models/feedback.model';

@Component({
  selector: 'app-user-feedback',
  templateUrl: './user-feedback.component.html',
  styleUrls: ['./user-feedback.component.css'],
})
export class UserFeedbackComponent {
  feedback: Feedback = {
    customerName: '',
    email: '',
    message: '',
  };

  constructor(private feedbackService: UserFeedbackService) {}

  onSubmit(): void {
    this.feedbackService.submitFeedback(this.feedback).subscribe({
      next: () => {
        alert('✅ Feedback submitted successfully!');
        this.feedback = { customerName: '', email: '', message: '' };
      },
      error: () => {
        alert('❌ Failed to submit feedback.');
      },
    });
  }
}
<h2>Submit Feedback</h2>
<form (ngSubmit)="onSubmit()" #form="ngForm">
  <label>Name:</label>
  <input
    type="text"
    [(ngModel)]="feedback.customerName"
    customerName="name"
    required
  /><br />

  <label>Email:</label>
  <input
    type="email"
    [(ngModel)]="feedback.email"
    customerName="email"
    required
  /><br />

  <label>Message:</label>
  <textarea
    [(ngModel)]="feedback.message"
    customerName="message"
    required
  ></textarea
  ><br />

  <button type="submit" [disabled]="form.invalid">Submit</button>
</form>
